fn count_uppercase(text: &Vec<char>) -> u64 {
    // Use iterator and filter by uppercase condition
    // 'A' as char is 65; 'Z' is 90 in ASCII
    // char implements PartialOrd, so range comparison works naturally
    let count = text.iter()
        .filter(|&&c| c >= 'A' && c <= 'Z')
        .count();

    count as u64
}